WITH cleaned AS (SELECT *, LAST_DAY(opened_date) opened_date_month_end, DATE_SUB(opened_date, 20) opened_date_minus_20d, COALESCE(status, 'NONE') resolved_status FROM accounts WHERE customer_id IS NOT NULL), enriched AS (SELECT id, customer_id, account_type, balance, opened_date, opened_date_month_end, CUME_DIST() OVER (PARTITION BY customer_id, account_type ORDER BY balance DESC) balance_cume_dist, SUM(balance) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_balance, ROW_NUMBER() OVER (ORDER BY opened_date_month_end, id) event_seq, STDDEV_SAMP(balance) OVER (PARTITION BY account_type, status) account_type_stddev_samp_balance FROM cleaned WHERE MONTH(opened_date_month_end) IN (2, 7, 12)), metrics AS (SELECT id, account_type, balance, opened_date, cumulative_balance, account_type_stddev_samp_balance, SUM(balance) OVER (PARTITION BY account_type, customer_id ORDER BY event_seq, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) running_balance, SUM(balance) OVER (PARTITION BY customer_id ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_balance_2 FROM enriched), cleaned_accounts AS (SELECT *, COALESCE(running_balance, 0) running_balance_filled, ROUND(running_balance * 0.85, 2) adjusted_running_balance FROM metrics WHERE account_type IN ('CREDIT', 'CHECKING', 'SAVINGS')) SELECT id, account_type, balance, cumulative_balance, account_type_stddev_samp_balance, running_balance, cumulative_balance_2, CASE WHEN account_type RLIKE '^(LOAN|SAVINGS)$' THEN 'GROUP_A' WHEN account_type RLIKE '^(CHECKING|CREDIT)$' THEN 'CORE' ELSE 'EXTENDED' END AS account_type_zone FROM cleaned_accounts;
